from collections import defaultdict

def solve(n, m, queries):
    matrix = [[0] * (m+1) for _ in range(n+1)]
    connected_components = 0
    components = {0}

    for x, y, c in queries:
        if matrix[x][y] != c:
            matrix[x][y] = c
            for dx, dy in [(0, 1), (1, 0)]:
                nx, ny = x + dx, y + dy
                if 0 < nx <= n and 0 < ny <= m and matrix[x][y] == matrix[nx][ny]:
                    connected_components += 1
                    if connected_components not in components:
                        components.add(connected_components)

    max_visited = 0
    while matrix:
        visited, x = defaultdict(int), 0
        queue = [matrix[x]]
        visited[x] = 0

        while queue:
            x = queue.pop()
            visited.update({x: max_visited + 1})
            for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx, ny = x[0] + dx, x[1] + dy
                if 0 < nx <= n and 0 < ny <= m and matrix[nx][ny] not in visited:
                    queue.append(matrix[nx][ny])
                    visited[matrix[nx][ny]] = max_visited + 1

        for x in visited:
            if max_visited < visited[x]:
                max_visited = x

    while m > 0 or n > 0:
        if matrix[n-1][m-1] in components:
            m -= 1
            n -= 1
        elif m > 0:
            matrix[n][m] = 0
            components.discard(connected_components)
            connected_components -= 1
            if not components:
                break
            max_visited -= 1
            m -= 1
        elif n > 0:
            matrix[n][m] = 0
            components.discard(connected_components)
            connected_components -= 1
            if not components:
                break
            max_visited -= 1
            n -= 1

    return components
