import sys

def perform_queries(n, m, q):
    queries = []
    counts = []

    for _ in range(q):
        x, y, c = map(int, sys.stdin.readline().strip().split())
        queries.append((x, y, c))
        counts.append(0)

    # Edge case for the first query
    if n > 1:
        counts[0] += 1

    for i in range(q):
        x, y, c = queries[i]
        if c == 1:
            current_count = counts[0]
            for j in range(1, n):
                if x == j and y == 1 or x == 1 and y == j:
                    current_count -= 1
                    if counts[j] < current_count:
                        counts[j] = current_count
                else:
                    current_count = 0
                    break
        else:
            for j in range(1, n):
                if x == j and y == 1 or x == 1 and y == j:
                    current_count -=1
                else:
                    current_count += 1
                if current_count == 0 and i != (q - 1):
                    counts[i+1] += 1
                    break
        counts[i] = 0

    return counts

