from collections import defaultdict

class Graph:
    def __init__(self, vertices):
        self.v = vertices
        self.graph = defaultdict(list)

    def add_edge(self, u, v):
        self.graph[u].append(v)
        self.graph[v].append(u)

    def dfs(self, v, path, k, distances):
        if k == 0:
            return path[-1]
        if k in distances:
            return path[-1]
        for child in self.graph[v]:
            if child not in distances:
                distances[child] = 0
                path.append(child)
                res = self.dfs(child, path[:], k - 1, distances)
                path.pop()
                distances[child] = -1 if res is None else res + 1
        return len(path) == 1

    def query_2(self, v, h):
        path = [v]
        distance = {v: 0}
        while v in distance and h >= distance[v]:
            v = path.pop()
            distances = []
            result = self.dfs(v, path[:], h - 1, distance)
            if result is not None:
                distance[result] = h
                distances.append(result)
            v = path[-1]
        return distances.pop()

    def query_3(self, v, k):
        path = [v]
        if self.dfs(v, path[:], k, {v}) is None:
            return None
        else:
            distances = self.leaf_dist(v)
            return {d: idx for idx, d in enumerate(distances) if d >= k}

    def leaf_dist(self, root):
        stack = [(root, 0)]
        distances = defaultdict(int)
        leaf_dist = []
        while stack:
            u, dist = stack.pop()
            distances[u] = dist
            stack.append((u, dist + 1))
            for child in self.graph[u]:
                if child in distances and distances[child] == dist + 1:
                    stack.append((child, dist + 1))
                elif child not in distances and dist + 1 != distances[child] and distances[child] >= 0:
                    stack.append((child, dist + 1))
        leaf_dist.extend((idx + 1, d) for idx, d in enumerate(distances) if d == -1)
        leaf_dist.sort(reverse=True)
        return leaf_dist
