def read():
    return map(int, input().split())

def build_graph(N, data):
    G = {n: [] for n in range(N)}
    for i, H in data:
        G[i].append((H, i))
    return G

def dp(G, D):
    N = len(G)
    inf = 10**9
    dp = [[[inf for d in range(D + 1)] for i in range(N)] for _ in range(N)]
    visited = {i: -1 for i in range(N)}
    q = deque([(-inf, -1, -1)])
    while q:
        d, i, j = q.popleft()
        if d < 0:
            best = qcounts[i] + 1 if i in qcounts else inf
            for h, k in G[i]:
                next_d = max(d, k)
                count = dp[i][j][k] = min(dp[i][j][k], best)
                while q and q[-1] <= next_d:
                    q.pop()
                q.append((next_d, i, j))
        else:
            dp[i][j][d] = d
    return dp, visited

def query(x, y, v, G, dp, visited):
    best, count = inf, 0
    for h, i in G[x]:
        if h >= v or visited[i] == x:
            continue
        count += 1
        best = min(best, y in dp[i][y][v-1])
    return best * v + count

def solve(N, D, U, Q, data, queries):
    G = build_graph(N, data)
    dp, visited = dp(G, D)
    for _ in range(U + 1):
        for query in range(U):
            x, y, v = queries[query]
            res = query(x, y, v, G, dp, visited)
