def find_min_prime_divisor(prices, recipes):
    from math import isqrt
    from itertools import product
    from sympy import primerange
    primes = list(primerange(1, isqrt(max(prices) * max(recipes)) + 10))
    min_prime_divisor = float('inf')
    for recipe in recipes:
        di, symbols, ci = recipe.partition(' ')
        di, ci = int(di), int(ci)
        for digits in product(range(di), repeat=len(symbols)):
            di_value = sum(d * digits[i] for i, d in enumerate(digits) if d != '?')
            ci_value = ci + di * di_value
            for prime in primes:
                if ci_value % prime == 0:
                    break
            else:
                min_prime_divisor = min(min_prime_divisor, prime)
        else:
            for prime in primes:
                if ci_value % prime == 0:
                    min_prime_divisor = min(min_prime_divisor, prime)
    return -1 if min_prime_divisor > 100 else min_prime_divisor

