    elif e == 2:
        result.pop()
        if depth[vertex] == depth[target] + 1 and vertex != target:
            del visited[vertex]
            depth[vertex] = -1  # Make vertex disconnected
        else:
            for child in graph[vertex]:
                if child != parent and vertex < target:
                    target, speed = child, impedance(child)
                elif child != parent and vertex > target:
                    target, speed = child, impedance(child)
                else:
                    target, speed = child, impedance(child)

def impedance(current, parent=None):
