        if coefficients[i] % k != 0:
            return False
    return True

def can_win(coeffs):
    if sum(coeffs[:n:]) % k != 0:
        return True
    for i in range(n, 0, -1):
        if sum(coeffs[:i]) % k == 0:
            if can_win(coeffs[:i]):
                return True
    return False

def find_k_value():
    for i in range(1, n + 2):
        for j in range(-i, i + 1):
            if i - j % i == 0 and pow(-1, i - j % i) % (k + 1) == 1:
                return i - j % i, True
    return n + 1, False

def has_winning_strategy(coeffs):
    if can_win(coeffs):
        return "Yes"
    k, exists_k = find_k_value()
    if not exists_k:
        return "No"
    filled_polynomial = [coeffs[0]]
    for i in range(1, n + 2):
        filled_polynomial.append(k)
    if is_divisible_by_k(filled_polynomial, k):
        return "Yes"
    for i in range(1, n + 2):
        if filled_polynomial[i] != coeffs[i]:
            filled_polynomial[i] += 1 if filled_polynomial[i] < k else -1
    if is_divisible_by_k(filled_polynomial[:-1], k):
        return "Yes"
    return "No"

