    visited = set()
    for r in range(n):
        for c in range(m):
            if matrix[r][c] > 0 and (r, c) not in visited:
                visited.add((r, c))
                queue = deque([(r, c)])
                component = set([(r, c)])
                component_count += 1
                while queue:
                    r, c = queue.popleft()
                    for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and matrix[nr][nc] > 0 and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            matrix[nr][nc] -= 1
                            component_count += 1
                            queue.append((nr, nc))
