import math

def ball_behavior(radius, distance):
    # The ball will hit a circle after traveling a distance equal to or more than 2 times its radius.
    return (distance // 2 * radius) + (radius % distance) > 0

def calculate_points(circles, ball_angle, ball_distance):
    points = 0
    max_hits = 0
    for circle in circles:
        # Compute the points for each circle the ball can hit.
        dist_to_center = math.sqrt(circle[0]**2 + circle[1]**2)
        if ball_behavior(circle[2], ball_distance):
            # If the circle is at least 2*d away from the origin, the ball will hit it once.
            if dist_to_center > ball_distance:
                max_hits += 1
            elif ball_behavior(circle[2], 2*ball_distance):
                # If the circle is exactly at d away from the origin, the ball will hit it twice.
                if dist_to_center == ball_distance:
                    max_hits += 2
        # If the ball is close enough to hit the circle, increase points.
        elif ball_behavior(circle[2], dist_to_center):
            max_hits += 1
    return max_hits

def solve(n, distance, circles):
    max_points = 0
    for angle in range(360):
        for circle in circles:
            collected_points = calculate_points(circles, angle, distance)
            max_points = max(max_points, collected_points)
    return max_points

