import sys

def find_optimal_pos(M, a, b):
    rows, cols = len(M), len(M[0])
    if a > rows or b > cols:
        return None

    min_height = 10**9
    res_row, res_col = -1, -1

    for i in range(rows - a + 1):
        for j in range(cols - b + 1):
            cur_min = min(min(M[i][j:j+b]), min(M[i+1][j:j+b]), min(M[i][j+1:j+b]), min(M[i+1][j+1:j+b]))
            if cur_min < min_height:
                min_height = cur_min
                res_row, res_col = i, j

    return res_row, res_col, min_height

def construct_cities(M, a, b):
    cities = []
    n, m = len(M), len(M[0])
    for i in range(n - a + 1):
        for j in range(m - b + 1):
            row, col, height = find_optimal_pos(M, a, b)
            if row != None:
                cities.append((row, col, height))

    return cities

