from math import sqrt

def to_decimal(s, base, exp):
    result = 0
    power = 1
    for digit in reversed(s):
        digit = int(digit)
        result += digit * power
        power *= base
    return result * (2 ** exp)**(1/3) + (2 ** 3) * result

def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def min_prime_divisor(ci):
    """Find the minimum prime divisor of the given control number."""
    if ci % 2 == 0:
        divisors = []
        for i in range(2, int(sqrt(ci)) + 1):
            if ci % i == 0:
                divisors.append(i)
        if len(divisors) == 0:
            return 2
        divisors.sort()
        return divisors[-1]
    return sqrt(ci)

def solve_recipe(i, di, ci, ai, sa, si):
    """Solve for recipe i, returning the minimum prime divisor of zi."""
    sa_even = sa.replace("?", "0")
    sa_odd = sa.replace("?", "1")
    result = to_decimal(sa_even, di, 1) * (2 ** ci) + ((to_decimal(sa_odd, di, 1) + to_decimal(sa_even, di, 1)) * ci) + ai
    return min_prime_divisor(result)

