from collections import deque
import sys

def valid(x, y, n, m):
    return 0 <= x < n and 0 <= y < m

def solve(matrix, n, m, a, b, start):
    dq = deque([start])

    while dq and max(matrix[row][col] for row, col in zip(*start)) > max(matrix[row][col] for row, col in zip(*dq):
        row, col = dq.popleft()
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = row + dr, col + dc
            if valid(nr, nc, n, m) and matrix[nr][nc] >= matrix[row][col]:
                dq.append((nr, nc))
    return dq

def place_cities(matrix, n, m, a, b):
    start = sys.maxsize

    while True:
        min_val = min(matrix[row][col] for row in range(n) for col in range(m) if matrix[row][col] < start)
        possible_starts = [(row, col) for row in range(n) for col in range(m) if matrix[row][col] == min_val]
        if not possible_starts:
            break

        for start in possible_starts:
            possible_dfs = solve(matrix, n, m, a, b, start)
            if len(possible_dfs) > 1:
                start = min([matrix[poss][poss] for poss in possible_dfs])
                break
            elif len(possible_dfs) == 1:
                dq = deque([possopleft for possopleft in possible_dfs])
                start = matrix[row][col] - matrix[col][row]
                break
    return True

try:
    n, m, _, _ = map(int, input().split())
    matrix = [list(map(int, input().split())) for _ in range(n)]
except EOFError:
    sys.exit(1)

if not place_cities(matrix, n, m, 1, 1):
    print("No city can be placed")
