def can_human_win(n: int, nk: int) -> str:
    if n == 1:
        return "No" if nk < 0 else "Yes"

    # Variables to store positions with undefined coefficients
    positions = []
    for i in range(n + 1):
        if nk * i <= positions[-1] if nk != 0 else -10000 <= positions[-1]:
            positions.append(i)

    # Count positive turns (on human's side) and even negative remainders
    human_turns_pos = 0
    remainder_counter = [0] * 2
    for i in range(n + 1):
        if positions[i] > 0:
            human_turns_pos += 1
        if nk * i % 2 == 0:
            remainder_counter[nk * i % 2] += 1

    # Check if the computer or one human turn per unknown coefficient results in a win
    if nk == 0 or human_turns_pos > remainder_counter[nk]:
        return "Yes"
    else:
        return "No"


