                return 1 in P.keys() and find_division_possible(P, n + 1)
            else:
                return k % a % 2 == 0 and find_division_possible(P - {k % a}, n + 2)

    return k not in P or any({1} - P if (-math.floor(1/a)).is_integer() else {a})

n, k = map(int, input().split())
coeffs = dict(map(int, input().split()))
print('Yes' if find_division_possible(coeffs, k) else 'No')
