import sys
from typing import List, Tuple

def find_optimal_position(heights: List[List[int]], start: Tuple[int, int]) -> Tuple[int, int]:
    min_height = min(heights[start[0]][start[1]], max(heights[start[0] - 1][start[1]], heights[start[0]][start[1] - 1]))
    min_dist = float('inf')
    for i in range(start[0]):
        for j in range(start[1]):
            if heights[i][j] == min_height:
                min_dist = min(min_dist, abs(i - start[0]) + abs(j - start[1]))
    return start[0] + min_dist, start[1] + min_dist

def construct_cities(n: int, m: int, a: int, b: int, heights: List[List[int]]) -> List[Tuple[int, int, int]]:
    _, _, amount = 0, 0, 0
    k = 0
    pos = (a - 1, b - 1)
    cities = []

    while amount < a * b:
        pos, amount = find_optimal_position(heights, pos)
        k += 1
        cities.append((pos[0] + 1, pos[1] + 1, amount))
        for i in range((pos[0] + 1) % a):
            for j in range((pos[1] + 1) % b):
                heights[(pos[0] - i) % a][(pos[1] - j) % b] -= amount
    return cities

def main():
    n, m, a, b = map(int, input().split())
    heights = [list(map(int, input().split())) for _ in range(n)]

    cities = construct_cities(n, m, a, b, heights)

    nlines = len(cities)
    for _ in range(nlines):
        print(nlines, cities[_][0], cities[_][1], cities[_][2])

if __name__ == "__main__":
    main()
