import math

def calculate_points(direction, distance, circles):
    x, y, r = direction
    points = 0

    if round(x**2 + y**2, 2) <= math.pow(distance, 2):
        if r >= distance - math.sqrt(x**2 + y**2):
            points += 1
    elif round(x**2 + y**2 - 2*r*r, 2) <= math.pow(distance, 2):
        if r >= math.sqrt(distance**2 - (x**2 + y**2 - 2*r*r)):
            points += 1
    return points

def max_points_circle(d, centers_and_radii):
    max_points = 0
    for direction, distance in extend(d):
        for circles in centers_and_radii:
            points = calculate_points(direction, distance, circles)
            if points > max_points:
                max_points = points
    return max_points

def extend(distance):
    X = []
    while True:
        x = random.uniform(-distance, distance)
        y = random.uniform(-distance, distance)
        r = random.uniform(0, distance)
        if round(x**2 + y**2, 2) <= math.pow(distance, 2) and (x, y, r) not in X:
            yield (x, y, r) * r / distance
            X.append((x, y, r))
        elif round(x**2 + y**2 - 2*r*r, 2) <= math.pow(distance, 2) and ((x, y) + (r, 0)) not in X:
            yield ((x, y), r) * r / distance - (x, y)
            X.append(((x, y), r))
        else:
            break

def read_data():
    return int(input().split()[0]), int(input().split()[1])

data = read_data()
print(max_points_circle(data[0], [(x, y, data[1]) for x, y in read_data()]))
