def is_divisible_by_linear(polynomial, k):
    coefficients = polynomial[:]
    x_k = coefficients[k]
    if x_k == 0:
        return True
    for i in range(len(coefficients)):
        if i != k and coefficients[i] != 0 and coefficients[i] % x_k == 0:
            return True
    return False

def can_guarantee_win(n, k, initial_polynomial):
    if not is_divisible_by_linear(initial_polynomial, k):
        return "Yes"
    for j in range(1, n + 1):
        if initial_polynomial[j] == '?':
            polynomial_copy = initial_polynomial[:]
            polynomial_copy[j] = 0
            if not is_divisible_by_linear(polynomial_copy, k):
                return "Yes"
            polynomial_copy[j] = 1
            if not is_divisible_by_linear(polynomial_copy, k):
                return "Yes"
    return "No"

# Example usage
n, k = map(int, input().split())
if '?' in input():
    print(can_guarantee_win(n, k, eval(input())))
else:
    print("No")
